if (nzchar(Sys.getenv("HCC_AUDIT_RLIB"))) .libPaths(Sys.getenv("HCC_AUDIT_RLIB")); suppressPackageStartupMessages({library(Matrix); library(data.table)})
O <- file.path(Sys.getenv("HCC_AUDIT_ROOT", "."), "N11_out/hiend_m9_hvg")
WTs <- readRDS(file.path(O, "WT_network.rds"))
DRs <- as.data.frame(readRDS(file.path(O, "ko_speedtest/ALAD.rds"))); DRo <- as.data.frame(readRDS(file.path(O, "official_ALAD_diffRegulation.rds")))
cat("shared WT dim", dim(WTs), " names identical sets:", setequal(rownames(WTs), DRo$gene), "\n")
cat("DR rows", nrow(DRs), nrow(DRo), " same gene set:", setequal(DRs$gene, DRo$gene), "\n")
cat("head official genes:", head(DRo$gene, 5), "\n"); cat("head shared genes:", head(DRs$gene, 5), "\n")
m <- merge(DRs, DRo, by = "gene", suffixes = c(".s", ".o"))
for (k in c("distance", "Z", "FC", "p.value", "p.adj")) cat(k, " max|diff| after aligning by gene:", max(abs(m[[paste0(k, ".s")]] - m[[paste0(k, ".o")]])), " spearman:", round(cor(m[[paste0(k, ".s")]], m[[paste0(k, ".o")]], method = "spearman"), 4), "\n")
cat("sig shared:", DRs$gene[DRs$p.adj < 0.05], " | sig official:", DRo$gene[DRo$p.adj < 0.05], "\n")
